//! Relations: what the methods generated by `has_many` and `belongs_to` call.
//!
//! Every loader is one query through the query builder, whatever the number of rows it loads
//! for: `"order_id" = ANY($1)` with the keys as one array parameter, then the rows grouped in a
//! `HashMap`. That is the cure for N+1, the loop that sends one query per parent (orm/PLAN.md
//! §12). Nothing is loaded behind a field access: each round trip is a call you can see.

use std::collections::{HashMap, HashSet};
use std::future::Future;
use std::hash::Hash;

use tokio_postgres::types::ToSql;

use crate::error::Error;
use crate::executor::Executor;
use crate::query::{Column, Value};
use crate::table::Table;

/// A foreign key's field: the key of the row it points at (`order_id: i64`), or an `Option` of
/// it for a nullable foreign key. Generated code reads it to group rows by their parent.
#[doc(hidden)]
#[diagnostic::on_unimplemented(
    message = "a foreign key of type `{Self}` cannot refer to a key of type `{K}`",
    label = "the foreign key's field",
    note = "a foreign key has the type of the key it refers to, or an `Option` of it"
)]
pub trait ForeignKey<K> {
    /// The key it refers to; `None` for a NULL.
    fn key(&self) -> Option<&K>;
}

impl<K> ForeignKey<K> for K {
    fn key(&self) -> Option<&K> {
        Some(self)
    }
}

impl<K> ForeignKey<K> for Option<K> {
    fn key(&self) -> Option<&K> {
        self.as_ref()
    }
}

/// `has_many`, one parent: the rows of `C` whose `column` holds `key`, in `C`'s key order.
#[doc(hidden)]
pub fn children<C, T, E>(
    db: &E,
    column: Column<C, T>,
    key: impl Value<T>,
) -> impl Future<Output = Result<Vec<C>, Error>> + Send
where
    C: Table,
    T: ToSql + Sync + Send + 'static,
    E: Executor,
{
    let query = C::query().filter(column.eq(key));
    async move { query.all(db).await }
}

/// `has_many`, many parents in one query: the rows of `C` whose `column` holds one of
/// `parents`' keys, grouped by the parent `fk` points at. The `Vec` at `i` holds `parents[i]`'s
/// rows, in `C`'s key order; a parent given twice gets its rows at its first place.
#[doc(hidden)]
pub fn load_children<'a, P, C, T, F, E>(
    db: &'a E,
    parents: &'a [P],
    column: Column<C, T>,
    fk: fn(&C) -> &F,
) -> impl Future<Output = Result<Vec<Vec<C>>, Error>> + Send
where
    P: Table,
    P::Key: Value<T> + Hash + Eq + Clone,
    C: Table,
    T: ToSql + Sync + Send + 'static,
    F: ForeignKey<P::Key>,
    E: Executor,
{
    let keys: Vec<P::Key> = parents.iter().map(P::key).collect();
    async move {
        if parents.is_empty() {
            return Ok(Vec::new());
        }
        let children = C::query().filter(column.any(keys)).all(db).await?;
        let mut groups: HashMap<P::Key, Vec<C>> = HashMap::new();
        for child in children {
            if let Some(key) = fk(&child).key() {
                groups.entry(key.clone()).or_default().push(child);
            }
        }
        Ok(parents
            .iter()
            .map(|parent| groups.remove(&parent.key()).unwrap_or_default())
            .collect())
    }
}

/// `belongs_to` with a nullable foreign key: the row it points at, or `None` for a NULL.
#[doc(hidden)]
pub async fn parent_opt<P, E>(db: &E, key: Option<&P::Key>) -> Result<Option<P>, Error>
where
    P: Table,
    E: Executor,
{
    match key {
        Some(key) => P::find(db, key).await.map(Some),
        None => Ok(None),
    }
}

/// `belongs_to`, many rows in one query: the rows of `P` that `children` point at through `fk`,
/// by key. Each one is loaded once, however many children point at it.
#[doc(hidden)]
pub fn load_parents<'a, P, C, F, E>(
    db: &'a E,
    children: &'a [C],
    fk: fn(&C) -> &F,
) -> impl Future<Output = Result<HashMap<P::Key, P>, Error>> + Send
where
    P: Table,
    P::Key: ToSql + Hash + Eq + Clone + 'static,
    F: ForeignKey<P::Key>,
    E: Executor,
{
    let keys: HashSet<&P::Key> = children.iter().filter_map(|c| fk(c).key()).collect();
    let keys: Vec<P::Key> = keys.into_iter().cloned().collect();
    async move {
        if keys.is_empty() {
            return Ok(HashMap::new());
        }
        // The parent's key column: a relation follows a single-column key.
        let key = Column::<P, P::Key>::new(P::KEY_COLUMNS[0]);
        let parents = P::query().filter(key.any(keys)).all(db).await?;
        Ok(parents.into_iter().map(|p| (p.key(), p)).collect())
    }
}
